PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE regime_history (
        id INTEGER PRIMARY KEY,
        date TEXT NOT NULL UNIQUE,
        spy_close REAL,
        ma_8 REAL,
        ma_21 REAL,
        qqq_close REAL,
        qqq_ma_8 REAL,
        qqq_ma_21 REAL,
        regime TEXT NOT NULL,
        cross_date TEXT,
        cross_days_ago INTEGER,
        size_modifier REAL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
COMMIT;
